function composeHuntMarkers(people:HuntPersonRow[],positions:HuntPositionRow[],locations:HuntLocationRow[]){const byId=new Map(people.map(p=>[p.id,p]));const staticMarkers:HuntMapMarker[]=positions.flatMap(position=>{const person=position.assigned_participant_id?byId.get(position.assigned_participant_id):null,coords=position.location?.coordinates;return person&&coords?.length===2?[{id:position.id,name:huntPersonName(person,people,nameDisplay)+' · K'+position.number,role:person.role,coordinates:coords}]:[];});const now=Date.now();const liveMarkers:HuntMapMarker[]=locations.flatMap(location=>{const person=byId.get(location.participant_id),age=now-Date.parse(location.recorded_at);return person&&age<5*60*1000?[{id:'live-'+location.participant_id,name:huntPersonName(person,people,nameDisplay)+' · '+(age>60000?'vana asukoht':'praegu'),role:person.role,coordinates:location.location.coordinates,live:true,stale:age>60000}]:[];});return [...staticMarkers,...liveMarkers];}
